'use strict';

// MODULES //

var isSignalReference = require( '@stdlib/plot/vega/base/assert/is-signal-reference' );
var isUndefined = require( '@stdlib/assert/is-undefined' );
var contains = require( '@stdlib/array/base/assert/contains' ).factory;
var copyJSON = require( './../../utils/copy_json.js' );
var signalName = require( './../../utils/signal_name.js' );


// VARIABLES //

var PROPS = [
	'bandPosition',
	'domain',
	'domainCap',
	'domainColor',
	'domainDash',
	'domainDashOffset',
	'domainOpacity',
	'domainWidth',
	'grid',
	'gridCap',
	'gridColor',
	'gridDash',
	'gridDashOffset',
	'gridOpacity',
	'gridWidth',
	'labelAlign',
	'labelAngle',
	'labelBaseline',
	'labelBound',
	'labelColor',
	'labelFlush',
	'labelFlushOffset',
	'labelFont',
	'labelFontSize',
	'labelFontStyle',
	'labelFontWeight',
	'labelLimit',
	'labelLineHeight',
	'labelOffset',
	'labelOpacity',
	'labelOverlap',
	'labelPadding',
	'labels',
	'labelSeparation',
	'maxExtent',
	'minExtent',
	'offset',
	'position',
	'tickBand',
	'tickCap',
	'tickColor',
	'tickCount',
	'tickDash',
	'tickDashOffset',
	'tickMinStep',
	'tickOffset',
	'tickOpacity',
	'ticks',
	'tickSize',
	'tickWidth',
	'title',
	'titleAlign',
	'titleAnchor',
	'titleAngle',
	'titleBaseline',
	'titleColor',
	'titleFont',
	'titleFontSize',
	'titleFontStyle',
	'titleFontWeight',
	'titleLimit',
	'titleLineHeight',
	'titleOpacity',
	'titlePadding',
	'titleX',
	'titleY',
	'zindex'
];

// Define a list of properties which need to be made explicitly "undefined" when set to falsy values:
var SPECIAL_PROPS = [
	'labelAlign',
	'labelBaseline',
	'labelBound',
	'labelFlush',
	'labelOverlap',
	'titleAngle',
	'titleBaseline',
	'titleX',
	'titleY'
];
var isSpecialProp = contains( SPECIAL_PROPS );

// FIXME: preferrably Vega would support signal updates here. For now, define a list of "structural" properties, as Vega does not currently support signal updates for toggling `domain`, `grid`, `labels`, and `ticks`. As a workaround, we keep them statically `true` and dynamically hide them by dropping their respective opacities to `0` when they are set to `false`.
var STRUCTURAL_PROPS = [
	'domain',
	'grid',
	'labels',
	'ticks'
];
var isStructuralProp = contains( STRUCTURAL_PROPS );

var OPACITY_PROPS = [
	'domainOpacity',
	'gridOpacity',
	'labelOpacity',
	'tickOpacity'
];
var isOpacityProp = contains( OPACITY_PROPS );

var OPACITY_TO_STRUCTURAL = {
	'domainOpacity': 'domain',
	'gridOpacity': 'grid',
	'labelOpacity': 'labels',
	'tickOpacity': 'ticks'
};


// MAIN //

/**
* Returns a transformed axis schema containing signals for use in conjunction with UI components.
*
* ## Notes
*
* -   The function mutates the provided list of signals.
*
* @private
* @param {Object} schema - axis schema
* @param {Array} signals - list of signals
* @param {Object} defaults - axis schema defaults
* @param {string} prefix - signal prefix
* @returns {Object} transformed schema
*/
function transform( schema, signals, defaults, prefix ) {
	var value;
	var name;
	var out;
	var k;
	var v;
	var i;

	out = copyJSON( schema );
	for ( i = 0; i < PROPS.length; i++ ) {
		k = PROPS[ i ];
		v = schema[ k ];
		if ( !isSignalReference( v ) ) {
			name = signalName( prefix+k );
			value = ( isUndefined( v ) ) ? defaults[ k ].default : v;

			if ( isSpecialProp( k ) ) {
				if ( isUndefined( v ) || v === '' || v === false ) {
					out[ k ] = void 0;
					signals.push({
						'name': name,
						'value': void 0
					});

					// Skip further processing...
					continue;
				}
			}
			if ( k === 'tickCount' ) {
				signals.push({
					'name': name,
					'value': ( value === '' ) ? void 0 : value
				});
			} else {
				signals.push({
					'name': name,
					'value': value
				});
			}
			if ( isStructuralProp( k ) ) {
				out[ k ] = true;
			} else if ( isOpacityProp( k ) ) {
				out[ k ] = {
					'signal': signalName( prefix+OPACITY_TO_STRUCTURAL[ k ] ) + ' ? ' + name + ' : 0'
				};
			} else if ( k === 'zindex' ) {
				// FIXME: preferably Vega would support signal references for `zindex`. Currently, Vega's internal `definition()` function coerces `zindex` using `+spec.zindex || undefined`, which means a signal reference object (e.g., `{ signal: '...' }`) yields `NaN` and is discarded. As a workaround, keep `zindex` as a plain numeric value.
				out[ k ] = value;
			} else {
				out[ k ] = {
					'signal': name
				};
			}
		}
	}

	// FIXME: Currently, Vega's `ariaGuide` reads `description` from `item.description` (the child visual item), not from `mark.description` (the group definition). Since `buildAxisEncode` does not map `description`, the value is never populated on the item and the custom description is silently ignored. As a workaround, inject the description via a custom `encode.axis.enter` mapping so that Vega copies it onto the visual item during initialization.
	if ( schema.description ) {
		// TODO: consider replacing the following logic with a call to `utils/deep-set` once refactored
		if ( !out.encode ) {
			out.encode = {};
		}
		if ( !out.encode.axis ) {
			out.encode.axis = {};
		}
		if ( !out.encode.axis.enter ) {
			out.encode.axis.enter = {};
		}
		out.encode.axis.enter.description = {
			'value': schema.description
		};
	} else if (
		out.encode &&
		out.encode.axis &&
		out.encode.axis.enter
	) {
		// TODO: determine whether it is possible to avoid using `delete` in order to avoid engine de-optimization
		delete out.encode.axis.enter.description;
	}
	return out;
}


// EXPORTS //

module.exports = transform;
